mapper.update:
update insp_plan
name = #{name}, cycle_type = #{cycleType}, cycle_value = #{cycleValue}, device_category = #{deviceCategory}, executor_id = #{executorId}, start_date = #{startDate}, generate_ahead_days = #{generateAheadDays}, last_generate_date = #{lastGenerateDate}, next_generate_date = #{nextGenerateDate}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select p.id, p.name, p.cycle_type, p.cycle_value, p.device_category, p.executor_id, s.name as executor_name, p.start_date, p.next_generate_date, p.status from insp_plan p left join sys_staff s on s.id = p.executor_id
and p.name like concat('%', #{name}, '%') and p.status = #{status}
order by p.id desc
